INSERT INTO "User"(id,email,"displayName","avatarUrl","googleId","isAdmin","premiumTier","createdAt","lastLoginAt","activeDays","preferredCountry","signupSource","collectionShareId") SELECT 'u'||g, 'user'||g||'@example.invalid','Name '||g,'https://lh3.googleusercontent.com/a/ACg8ocL'||md5(g::text),'1'||g::text||'0000000000',false,'premium',now(),now(),g%30,'US','organic',md5(g::text) FROM generate_series(1,10000) g;
INSERT INTO "PriceAlert"(id,email,"userId","cardId",finish,market,"lastPriceCents","targetCents","unsubToken","createdAt") SELECT 'a'||g,'user'||(g%10000+1)||'@example.invalid','u'||(g%10000+1),500000+(g*37)%200000,g%2,'US',1000+g%5000,900,md5(g::text||'x'),now() FROM generate_series(1,30000) g;
INSERT INTO "CollectionCard"(id,"userId","cardId","setId",condition,"isFoil",quantity,"costBasisCents","createdAt","updatedAt") SELECT 'c'||g,'u'||(g%10000+1),400000+(g*91)%300000,23000+g%400,'NM',g%5=0,1+g%3,100*(g%50),now(),now() FROM generate_series(1,100000) g;
INSERT INTO "Notification"(id,"userId",type,title,body,href,"createdAt") SELECT 'n'||g,'u'||(g%10000+1),'price-drop','Sol Ring dropped below your target of $1.50','Sol Ring (C21 267) is now $1.32 at 4 stores in the US.','/card/sol-ring-c21-267',now() FROM generate_series(1,100000) g;
INSERT INTO "ClickEvent"(id,retailer,page,slug,country,"createdAt") SELECT 'k'||g,'store:cardkingdom','card','sol-ring-c21-267','US',now() FROM generate_series(1,100000) g;
INSERT INTO "CardStat"("cardId","searchCount","viewCount","lastViewedAt") SELECT 400000+g*5, g%40, g%300, now() FROM generate_series(1,57000) g;
INSERT INTO "DemandDay"(day,data) SELECT to_char(now()-(g||' days')::interval,'YYYY-MM-DD'), (SELECT jsonb_object_agg((400000+i*7)::text, jsonb_build_array(i%90, i%700)) FROM generate_series(1,3000) i) FROM generate_series(1,90) g;
INSERT INTO "ImportRun"(kind,"startedAt","finishedAt",ok,summary) SELECT 'full',now(),now(),true,(SELECT jsonb_build_object('stores',jsonb_agg(jsonb_build_object('key','store'||i,'market','US','products',3000+i,'matched',2000+i,'offers',1500+i,'inStock',1400+i,'note','ok'))) FROM generate_series(1,110) i) FROM generate_series(1,400);
INSERT INTO "EbayPanel"("productId",market,"checkedAt",listings,graded) SELECT 400000+g,g%6,now(),(SELECT jsonb_agg(jsonb_build_object('finish',0,'priceCents',1000+i,'shipCents',399,'currency','USD','itemId','1234567890'||i,'title','Sol Ring Commander Collection Green C21 267 NM Magic the Gathering MTG','image','https://i.ebayimg.com/images/g/abc'||i||'/s-l500.jpg','rank',i)) FROM generate_series(1,8) i),NULL FROM generate_series(1,5000) g;
INSERT INTO "EbayBest"("productId",finish,market,"priceCents","shipCents","itemId","checkedAt") SELECT 400000+g,g%2,g%6,1000+g%900,399,'1234567890'||g,now() FROM generate_series(1,15000) g;
INSERT INTO "EbayTrack"(ref,market,tier,score,banner,"checkedAt","dueAt",matched) SELECT 'o:'||g,g%6,1+g%3,g*0.5,false,now(),now(),true FROM generate_series(1,5000) g;
INSERT INTO "EbayBanner"(key,payload,"updatedAt") VALUES ('v1',(SELECT jsonb_agg(jsonb_build_object('id',i,'name','Card name '||i,'img','https://i.ebayimg.com/images/g/x'||i||'/s-l300.jpg','cents',10000+i,'itemId','12345678'||i,'checkedAt',now())) FROM generate_series(1,400) i),now());
INSERT INTO "EbayLedger"("windowKey",cap,claimed,spent,"updatedAt") SELECT to_char(now()-(g||' days')::interval,'YYYY-MM-DD'),1000,900,880,now() FROM generate_series(1,30) g;
INSERT INTO "NewsletterSubscriber"(id,email,market,"createdAt","unsubToken") SELECT 'ns'||g,'sub'||g||'@example.invalid','US',now(),md5(g::text) FROM generate_series(1,5000) g;
INSERT INTO "SetReleaseAlert"(id,email,"setSlug",scope,market,"unsubToken","createdAt") SELECT 'sr'||g,'sub'||g||'@example.invalid','tla-avatar-the-last-airbender','set','US',md5(g::text),now() FROM generate_series(1,2000) g;
INSERT INTO "PublishedDeck"(id,slug,"userId",title,format,"commanderCardId","commanderName","commanderSlug",identity,list,lines,"cardIds","cardCount","publishedTotals","createdAt") SELECT 'd'||g,'deck-'||g,'u'||g,'Deck '||g,'commander',500000+g,'Atraxa','atraxa-praetors-voice',30,repeat('1 Sol Ring'||chr(10),99),(SELECT jsonb_agg(jsonb_build_object('cardId',400000+i,'qty',1)) FROM generate_series(1,99) i),ARRAY(SELECT 400000+i FROM generate_series(1,99) i),99,'{"US":25000}'::jsonb,now() FROM generate_series(1,300) g;
INSERT INTO "RisingSnapshot"(id,token,scope,title,data,"createdAt") SELECT 'rs'||g,md5(g::text),'GLOBAL','Hot 40',(SELECT jsonb_agg(jsonb_build_object('id',i,'name','Card '||i,'score',i,'reason','Searches are up and the price is near its range low.')) FROM generate_series(1,40) i),now() FROM generate_series(1,200) g;
INSERT INTO "SealedWatch"(id,"userId",email,market,"sealedId","targetCents","createdAt") SELECT 'sw'||g,'u'||(g%10000+1),'user'||(g%10000+1)||'@example.invalid','US',900000+g%3700,10000,now() FROM generate_series(1,3000) g;
INSERT INTO "PriceReport"(id,"productId",finish,kind,source,market,"storeName",issue,"createdAt") SELECT 'pr'||g,400000+g,0,'price','store:x','US','Store X','wrong price',now() FROM generate_series(1,2000) g;
INSERT INTO "SupportTicket"(id,number,email,name,subject,message,"createdAt","updatedAt") SELECT 'st'||g,g,'user'||g||'@example.invalid','Name','Question','Hello '||repeat('text ',40),now(),now() FROM generate_series(1,200) g;
INSERT INTO "Meta"(key,value,"updatedAt") SELECT 'k'||g, md5(g::text),now() FROM generate_series(1,20) g;
